class Registry {
    static int count;
    static { count = 1; System.out.println("init"); }

    static int bump() { return ++count; }
}

class Sub extends Registry {
    static int bump() { return 100; }
}

Registry first = new Registry();
System.out.println(Registry.bump());
Registry ref = new Sub();
System.out.println(ref.bump());

